proposals.refactored:
private static class WriterContext {
    StringWriter stringWriter;
    JsonWriter writer;
}

/** Sets up a JsonWriter that has written an empty array and has been closed once. */
private WriterContext createWriterContext() throws IOException {
    StringWriter stringWriter = new StringWriter();
    JsonWriter writer = new JsonWriter(stringWriter);
    writer.beginArray();
    writer.endArray();
    writer.close(); // first close
    WriterContext ctx = new WriterContext();
    ctx.stringWriter = stringWriter;
    ctx.writer = writer;
    return ctx;
}

@Test
public void testWriterCloseIsIdempotent_FirstClose() throws IOException {
    WriterContext ctx = createWriterContext();
    String actualJson = ctx.stringWriter.toString();
    assertEquals("String after first close should be []", "[]", actualJson);
}

@Test
public void testWriterCloseIsIdempotent_SecondClose() throws IOException {
    WriterContext ctx = createWriterContext();
    ctx.writer.close(); // second close
    String actualJson = ctx.stringWriter.toString();
    assertEquals("String after second close should still be []", "[]", actualJson);
}

