@ParameterizedTest
@CsvSource({
    "0, true",
    "1, true"
})
void testMixedCaseLiterals_TrueLiterals(int index, boolean expected) throws IOException {
    JsonReader reader = setupReaderForMixedCaseLiterals();
    for (int i = 0; i < index; i++) {
        reader.nextBoolean(); // skip preceding booleans
    }
    assertThat(reader.nextBoolean())
        .named(String.format("Boolean literal at position %d should be %s", index, expected))
        .isEqualTo(expected);
}

@ParameterizedTest
@CsvSource({
    "2, false",
    "3, false"
})
void testMixedCaseLiterals_FalseLiterals(int index, boolean expected) throws IOException {
    JsonReader reader = setupReaderForMixedCaseLiterals();
    for (int i = 0; i < index; i++) {
        reader.nextBoolean(); // skip preceding booleans
    }
    assertThat(reader.nextBoolean())
        .named(String.format("Boolean literal at position %d should be %s", index, expected))
        .isEqualTo(expected);
}

@ParameterizedTest
@CsvSource({
    "4",
    "5"
})
void testMixedCaseLiterals_NullLiterals(int index) throws IOException {
    JsonReader reader = setupReaderForMixedCaseLiterals();
    for (int i = 0; i < index; i++) {
        reader.skipValue(); // skip preceding tokens
    }
    assertThat(reader.peek())
        .named(String.format("Token at position %d should be NULL", index))
        .isEqualTo(JsonToken.NULL);
    reader.nextNull();
}

