    String publicDoc = "<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">";
    assertEquals("HTML output should keep PUBLIC DOCTYPE unchanged", publicDoc, htmlOutput(publicDoc));
    assertEquals("XML output should keep PUBLIC DOCTYPE unchanged", publicDoc, xmlOutput(publicDoc));

    String systemDoc = "<!DOCTYPE html SYSTEM \"exampledtdfile.dtd\">";
    assertEquals("HTML output should keep SYSTEM DOCTYPE unchanged", systemDoc, htmlOutput(systemDoc));
    assertEquals("XML output should keep SYSTEM DOCTYPE unchanged", systemDoc, xmlOutput(systemDoc));

    String legacyDoc = "<!DOCTYPE html SYSTEM \"about:legacy-compat\">";
    assertEquals("HTML output should keep legacy SYSTEM DOCTYPE unchanged", legacyDoc, htmlOutput(legacyDoc));
    assertEquals("XML output should keep legacy SYSTEM DOCTYPE unchanged", legacyDoc, xmlOutput(legacyDoc));
}

