private static void copyResourceToFile(String resourcePath, File destination) throws IOException {
    try (InputStream in = ParseTest.class.getResourceAsStream(resourcePath)) {
        if (in == null) {
            fail("Resource not found: " + resourcePath);
        }
        Files.copy(in, destination.toPath(), StandardCopyOption.REPLACE_EXISTING);
    }
}

