public void createsFormData_fields() {
    List<Connection.KeyVal> data = getFormData();

    String actual0 = data.get(0).toString();
    assertEquals("one=two", actual0,
            "Form field 'one' should have value 'two'.");

    String actual1 = data.get(1).toString();
    assertEquals("three=four", actual1,
            "Form field 'three' option 'four' should be selected.");

    String actual2 = data.get(2).toString();
    assertEquals("three=five", actual2,
            "Form field 'three' option 'five' should be selected.");

    String actual3 = data.get(3).toString();
    assertEquals("six=seven", actual3,
            "Form field 'six' textarea should contain 'seven'.");

    String actual4 = data.get(4).toString();
    assertEquals("seven=on", actual4,
            "Radio button 'seven' with value 'on' should be checked.");

    String actual5 = data.get(5).toString();
    assertEquals("eight=on", actual5,
            "Checkbox 'eight' should be checked by default.");
