/** Helper that verifies iterator order and exhaustion for non‑internal attributes. */
private void verifyIteratorOrderAndExhaustion(Attributes attrs) {
    Iterator<Attribute> it = attrs.iterator();
    assertTrue(it.hasNext());
    assertEquals("One", it.next().getKey());
    assertTrue(it.hasNext());
    assertEquals("Two", it.next().getKey());
    assertFalse(it.hasNext());
}

/** Helper that counts visible attributes and checks iterator exhaustion. */
private void verifyCountAndExhaustion(Attributes attrs) {
    int seen = countVisibleAttributes(attrs);
    assertEquals(EXPECTED_VISIBLE_COUNT, seen);

    Iterator<Attribute> it = attrs.iterator();
    assertTrue("Iterator should have a next element before consuming", it.hasNext());
    while (it.hasNext()) {
        it.next();
    }
    assertFalse("Iterator should be exhausted after consuming all visible attributes", it.hasNext());
}

/** Helper that counts non‑internal attributes using a foreach loop. */
private int countVisibleAttributes(Attributes attrs) {
    int count = 0;
    for (Attribute attribute : attrs) {
        count++;
    }
    return count;
}

