// ----- Helper methods -----
private Document parseSampleDocument() {
    return Jsoup.parse("<div>One <p>Two <p>Three");
}

private boolean hasAnyTextNode(Document doc) {
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                return true;
            }
        }
    }
    return false;
}

private TextNode findFirstTextNode(Document doc) {
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                return (TextNode) node;
            }
        }
    }
    return null;
}

private void assertAllTextNodesNonBlank(Document doc) {
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                TextNode textNode = (TextNode) node;
                assertFalse(StringUtil.isBlank(textNode.text()),
                        "TextNode text should not be blank");
            }
        }
    }
}

